appearances.css:
.mk{gap:3px}
.mk .intro{font-size:9px;line-height:1.3}
.intro:empty{display:none}
canvas{border-radius:3px;height:52px!important}
.box{padding:4px 5px;gap:3px;border-radius:3px;display:flex;flex-wrap:wrap;align-items:flex-start;gap:3px 1px}
.box>.row{display:contents}
.ctl{flex:0 0 56px;width:56px;min-width:0;display:grid;justify-items:center;gap:0}
.ctl:has(select){order:-1;flex:1 1 80px;width:auto;margin-right:3px}
.ctl:has(option[value=uni]),.ctl:has(option[value=i]){flex:2 1 140px}
.ctl label{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:0;font-size:7.5px;letter-spacing:-.02em;text-transform:none;line-height:1.15;text-align:center;max-width:100%;overflow-wrap:anywhere}
.ctl output{font-size:8px;line-height:1.1;letter-spacing:0;white-space:nowrap}
.ctl .kn{order:-1;width:28px!important;height:28px!important;justify-self:center!important}
.ctl .kn svg{width:100%;height:100%}
.ctl select{order:-1;width:100%;font-size:9px;letter-spacing:-.02em;padding:4px 2px;text-align:center;text-align-last:center;appearance:none;-webkit-appearance:none;border-radius:3px;min-height:26px}
.ctl:has(select) label{order:2}
.asg.box{display:grid}
.empty{padding:5px 8px;line-height:1.3;font-size:9px;border-radius:3px}
.asgbar,.asg{gap:4px}
.mk .prow{grid-template-columns:minmax(56px,1fr) auto minmax(70px,1.3fr) 32px 10px;gap:2px 5px;min-height:20px;font-size:10px}
.mk .prow select{grid-column:auto;font-size:9px;padding:1px 2px;min-height:22px;max-width:54px;border-radius:3px}
.mk .prow output{font-size:9px}
.mk .prow input[type=range]{height:14px}
.mk details.lane{padding:2px 5px;border-radius:3px}
.mk details.lane>summary{font-size:10px;padding:2px 0;letter-spacing:.04em}
.mk .tg h3{font-size:11px;margin:0 0 2px;gap:6px}
.mk .tg h3 small{font-size:9px}
.mk .asgbar input[type=search]{font-size:10px;padding:3px 6px;min-height:24px;flex:1 1 100px}
.mk .asgbar label.lab{font-size:9px;letter-spacing:0;text-transform:none;white-space:nowrap}
